(()=>{function boot(){const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const grid=document.querySelector('#news-flash .pinned-grid');if(grid&&!document.querySelector('[data-liu-appeal-pin]')){const hans=location.hostname.includes('globalprotectionwall')||new URLSearchParams(location.search).get('lang')==='zh-Hans';const c=document.createElement('article');c.className='home-card pinned-lead';c.dataset.liuAppealPin='';c.innerHTML='<a class="card-link home-media-report-action" href="'+(hans?'/child-advocacy-site/hearing-records/liu-zongxin-appeal-20261022/zh-Hans/':'/child-advocacy-site/hearing-records/liu-zongxin-appeal-20261022/')+'"><img alt="紙雕風格警察、城市與守護光帶意象，非事件現場" height="480" loading="eager" src="/child-advocacy-site/assets/art/liu-zongxin-appeal-20261022.svg" width="720"><div class="card-copy"><p class="card-meta">2026.10.22・旁聽筆記</p><h3>毒駕殺警案二審｜開庭重點</h3><p class="card-summary">影像勘驗、車窗爭議與故意／過失的法律判斷。</p><p class="card-source">現場整理，非正式法庭筆錄；事實與責任以法院最終認定為準。</p><span class="card-action">閱讀旁聽筆記 →</span></div></a>';grid.prepend(c);fetch('/child-advocacy-site/assets/art/liu-zongxin-appeal-court-thumb-20261023.webp.b64').then(r=>r.text()).then(b=>{const i=c.querySelector('img');if(i)i.src='data:image/webp;base64,'+b.trim()}).catch(()=>{})}const pin=document.querySelector('[data-liu-appeal-pin]');if(pin){fetch('/child-advocacy-site/assets/art/liu-zongxin-appeal-court-thumb-20261023.webp.b64').then(r=>r.text()).then(b=>{const i=pin.querySelector('img');if(i)i.src='data:image/webp;base64,'+b.trim()}).catch(()=>{})}document.querySelectorAll('[data-gsap-slider]').forEach(root=>{let cards=[...root.querySelectorAll(':scope>a')];const dated=cards.filter(c=>c.dataset.homeDate);if(dated.length){const maxDay=dated.map(c=>c.dataset.homeDate.slice(0,10)).sort().at(-1),cutoff=new Date(maxDay+'T00:00:00Z');cutoff.setUTCDate(cutoff.getUTCDate()-2);const cutoffDay=cutoff.toISOString().slice(0,10);cards.forEach(c=>{if(!c.dataset.homeDate||c.dataset.homeDate.slice(0,10)<cutoffDay)c.remove()});cards=[...root.querySelectorAll(':scope>a')].sort((a,b)=>b.dataset.homeDate.localeCompare(a.dataset.homeDate));cards.forEach(c=>root.append(c))}if(cards.length<2)return;let active=0,timer;function go(index,manual){active=(index+cards.length)%cards.length;const x=cards[active].offsetLeft-root.offsetLeft;if(window.gsap&&!reduce)window.gsap.to(root,{scrollLeft:x,duration:.62,ease:'power2.inOut',overwrite:true});else root.scrollTo({left:x,behavior:reduce?'auto':'smooth'});if(manual)restart()}function restart(){clearInterval(timer);if(!reduce)timer=setInterval(()=>go(active+1,false),7600)}const controls=document.createElement('div');controls.className='pinned-brief-slider-controls';controls.setAttribute('aria-label','Pinned brief controls');controls.innerHTML='<button type="button" aria-label="Previous brief">‹</button><button type="button" aria-label="Next brief">›</button>';controls.children[0].onclick=()=>go(active-1,true);controls.children[1].onclick=()=>go(active+1,true);root.after(controls);root.addEventListener('pointerdown',()=>clearInterval(timer),{passive:true});root.addEventListener('pointerup',restart,{passive:true});if(window.gsap&&!reduce)window.gsap.fromTo(cards,{autoAlpha:0,y:18},{autoAlpha:1,y:0,duration:.7,stagger:.1,ease:'power3.out',clearProps:'transform,opacity,visibility'});restart()})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot()})();